def update_files(self) -> None:
    """Update files when the config changed."""
    if not config.val.content.blocking.hosts.lists:
        try:
            os.remove(self._local_hosts_file)
        except FileNotFoundError:
            pass

    self.update_files()

    self._config_hosts_file = str(config_dir / "blocked-hosts")

def _is_blocked(self, request_url: QUrl, first_party_url: QUrl = None) -> bool:
    """Check whether the given request is blocked."""
    if not self.enabled:
        return False

    if first_party_url is not None and not first_party_url.isValid():
        first_party_url = None

    qtutils.ensure_valid(request_url)

    if not config.get("content.blocking.enabled", url=first_party_url):
        return False

    if blockutils.is_whitelisted_url(request_url):
        return False

    host = request_url.host().rstrip(".")
    if not request_url.scheme() and request_url.path() and "/" not in request_url.path():
        # QUrl parses a bare hostname as a relative path unless given a scheme.
        host = request_url.path().rstrip(".")
    blocked_hosts = self._blocked_hosts | self._config_blocked_hosts
    return any(
        candidate in blocked_hosts
        for candidate in urlutils.widened_hostnames(host)
    )

